feat1_t:'Desktop + mobile mix', feat1_d:'Two templates, one site. Each screen size gets a layout designed for it.',
feat2_t:'34 one-click plugins', feat2_d:'Shop, booking, menu, gallery, slideshow, reviews, FAQ, team, events, maps, newsletter and more.',
feat3_t:'Global languages', feat3_d:'The builder speaks 14 languages, and your site can auto-translate into 100+ languages with Google.',
feat4_t:'Your domain, your cloud', feat4_d:'You own everything. Host on Cloudflare Pages, Netlify, Vercel or any server.',
feat5_t:'SEO & analytics', feat5_d:'Title, description, keywords, share image, hreflang and your analytics code.',
feat6_t:'Videos & social', feat6_d:'YouTube videos, social links and WhatsApp, Telegram, LINE and WeChat buttons.',
faq_title:'Frequently asked questions',
faq1_q:'Do I need to know coding?', faq1_a:'No. Pick templates, type your content, switch plugins on and export. Everything happens in your browser.',
faq2_q:'Do you design the website for me?', faq2_a:'No. {brand} is fully self-service: you design your own site with our templates and plugins. We do not offer design services.',
faq3_q:'Can I sell products online?', faq3_a:'Yes. The online shop plugin adds products, sizes, stock, discount codes, a cart and a checkout that sends the order to your WhatsApp or email.',
faq4_q:'Do I need my own domain and hosting?', faq4_a:'Yes. You buy your own domain and choose your own cloud hosting. Our step-by-step guide shows how to connect them.',
faq5_q:'Which languages are supported?', faq5_a:'The builder has 14 languages. Your exported site can switch between them, or auto-translate into 100+ languages with Google.',
faq6_q:'How much does it cost?', faq6_a:'Two monthly plans: Pro HK$68 and Business HK$198. Your first month is paid upfront as a trial month; cancel anytime.',
cta_title:'Ready to build your site?', cta_sub:'Try the builder now. Start your trial month when you are ready to publish.',
