d_title:'Your domain & cloud hosting', d_sub:'You own your domain and your hosting. Follow these general steps to put your exported site online.',
d_s1_t:'Get a domain', d_s1_d:'Buy a domain from any domain registrar you like.',
d_s1_l1:'Choose a short, easy-to-spell name.', d_s1_l2:'Keep your registrar login safe — you will need it to edit DNS.', d_s1_l3:'Prices and renewal terms differ between registrars; check them on the registrar’s official site.',
d_s2_t:'Export your site', d_s2_d:'In the builder press “Export site”. You get one HTML file. Rename it to index.html and put it in a folder.',
d_s3_t:'Choose cloud hosting', d_s3_d:'Any static hosting works. Common choices:',
host_cf:'Create a Pages project in the Cloudflare dashboard, choose direct upload and upload your folder. You get a *.pages.dev address, then add your custom domain in the project settings.',
host_nf:'Drag and drop your folder onto Netlify (or connect a Git repository). Then open Domain management and add your custom domain.',
host_vc:'Create a project from a Git repository or with the Vercel CLI, deploy, then add your domain under Project Settings → Domains.',
host_vps:'On your own server, install Nginx, upload index.html to the web root and enable HTTPS with Let’s Encrypt.',
d_s4_t:'Point your domain (DNS)', d_s4_d:'At your registrar or DNS provider, add the records your host tells you. Typical setup:',
d_type:'Type', d_name:'Name', d_value:'Value (example)', d_when:'When to use',
d_cname_when:'www or a subdomain → the address your host gives you', d_a_when:'Root domain on a VPS → your server’s IP (example IP shown)',
d_s4_note:'Some hosts use ALIAS/ANAME or CNAME flattening for the root domain. Always copy the exact values from your host’s dashboard. DNS changes can take a while to apply.',
d_s5_t:'HTTPS & final check', d_s5_d:'Turn on HTTPS (most hosts do it automatically). Open your domain on a computer and a phone, add a product to the cart and send a test order.',
d_note:'We do not list third-party prices or free-tier limits because they change. Please check each provider’s official website.',
pr_title:'Simple monthly pricing', pr_sub:'Two self-service plans. Billed monthly, cancel anytime.',
