"feat2_d": "ショップ、予約、メニュー、ギャラリー、スライドショー、レビュー、FAQ、チーム、イベント、地図、ニュースレターなど。",
"feat3_t": "グローバル言語",
"feat3_d": "ビルダーは14言語を話します。サイトはGoogleで100以上の言語に自動翻訳できます。",
"feat4_t": "ドメイン、クラウド",
"feat4_d": "あなたもすべて所有しています。Cloudflareページ、Netlify、Vercel、またはサーバー上のホスト。",
"feat5_t": "SEOと分析",
"feat5_d": "タイトル、説明、キーワード、共有画像、hreflang、分析コード。",
"feat6_t": "ビデオ&ソーシャル",
"feat6_d": "YouTube動画、ソーシャルリンク、WhatsApp、Telegram、LINE、WeChatボタン。",
"faq_title": "よくある質問",
"faq1_q": "コーディングを知る必要がありますか?",
"faq1_a": "いいえ。テンプレートを選択し、コンテンツを入力し、プラグインをオン/エクスポートします。お使いのブラウザですべてが起こる。",
"faq2_q": "ウェブサイトをデザインしますか?",
"faq2_a": "いいえ。{brand} は完全セルフサービスです。テンプレートとプラグインを使ってご自身でサイトをデザインしていただきます。デザイン代行サービスは提供していません。",
"faq3_q": "オンラインで商品を販売できますか?",
"faq3_a": "はい。オンラインショッププラグインは、製品、サイズ、在庫、割引コード、カート、およびあなたのWhatsAppまたは電子メールに注文を送信するチェックアウトを追加します。",
"faq4_q": "自分のドメインとホスティングが必要ですか?",
"faq4_a": "はい。あなた自身のドメインを購入し、独自のクラウドホスティングを選択します。私たちのステップバイステップガイドは、それらを接続する方法を示しています。",
"faq5_q": "どの言語に対応していますか?",
"faq5_a": "ビルダーには14の言語があります。エクスポートされたサイトは、Googleで100以上の言語に自動翻訳できます。",
"faq6_q": "費用はいくらかかりますか?",
"faq6_a": "2つの月間プラン:プロHK$68およびビジネスHK$198。初月はトライアル月として前払いされます。いつでもキャンセルできます。",
"cta_title": "ウェブサイトを作る準備はできましたか？",
"cta_sub": "ビルダーを今すぐお試しください。公開準備ができたら、トライアル月を始めましょう。",
