"faq_title": "Foire aux questions",
"faq1_q": "Dois-je connaître le codage ?",
"faq1_a": "C'est pas vrai. Choisissez des modèles, tapez votre contenu, changez de greffons et exportez. Tout se passe dans votre navigateur.",
"faq2_q": "Concevez-vous le site pour moi ?",
"faq2_a": "Non. {brand} est entièrement en libre-service : vous concevez votre site avec nos modèles et plugins. Nous ne proposons pas de services de conception.",
"faq3_q": "Puis-je vendre des produits en ligne?",
"faq3_a": "Oui. Le plugin boutique en ligne ajoute des produits, tailles, stock, codes de réduction, un panier et une commande qui envoie la commande à votre WhatsApp ou email.",
"faq4_q": "Ai-je besoin de mon propre domaine et de mon hébergement ?",
"faq4_a": "Oui. Vous achetez votre propre domaine et choisissez votre propre hébergement cloud. Notre guide étape par étape montre comment les relier.",
"faq5_q": "Quelles langues sont prises en charge?",
"faq5_a": "Le constructeur a 14 langues. Votre site exporté peut basculer entre eux, ou auto-translate dans plus de 100 langues avec Google.",
"faq6_q": "Combien ça coûte ?",
"faq6_a": "Deux plans mensuels : Pro HK$68 et Business HK$198. Votre premier mois est payé à l'avance comme mois d'essai; annuler à tout moment.",
