"step3_d": "अपना नाम, लोगो, रंग और टेक्स्ट संपादित करें, फिर प्लगइन्स पर स्विच करें: ऑनलाइन दुकान, बुकिंग, मेनू, गैलरी, वीडियो और अधिक।",
"step4_t": "आपका डोमेन + आपका क्लाउड, जीना",
"step4_d": "एक फ़ाइल निर्यात करें, इसे अपनी खुद की क्लाउड होस्टिंग पर अपलोड करें और अपने खुद के डोमेन को इंगित करें।",
"shop_hl_badge": "शीर्षक",
"shop_hl_title": "अपनी खुद की ऑनलाइन दुकान",
"shop_hl_sub": "किसी भी टेम्पलेट को दुकान में बदल दें। उत्पाद जोड़ें, ग्राहकों को एक गाड़ी भरने और सीधे अपने WhatsApp या ईमेल पर ऑर्डर भेजने दें।",
"shop_hl_1": "उत्पाद, आकार और स्टॉक",
"shop_hl_1d": "प्रत्येक उत्पाद के लिए फोटो, मूल्य, श्रेणी, आकार या रंग, स्टॉक बैज और वीडियो।",
"shop_hl_2": "कार्ट, मात्रा और छूट कोड",
"shop_hl_2d": "एक गाड़ी जो आइटम को याद करती है, मात्रा, छूट कोड और लाइव कुल के साथ।",
"shop_hl_3": "व्हाट्सएप या ईमेल द्वारा चेकआउट",
"shop_hl_3d": "ऑर्डर आइटम, कुल और ग्राहक विवरण के साथ एक तैयार-से-रीड संदेश के रूप में आते हैं।",
"shop_hl_4": "कार्ड और पेपाल तैयार",
"shop_hl_4d": "वैकल्पिक स्ट्रिप भुगतान लिंक प्रति उत्पाद और एक पेपैल चेकआउट; बाद में पूर्ण प्रवेश द्वार।",
"shop_hl_cta": "दुकान प्लगइन की कोशिश करो",
"demo_p1": "एचके दूध चाय",
"demo_p2": "स्ट्रॉबेरी",
"demo_p3": "ग्रीन एप्पल",
"demo_p4": "मैच",
"feat_title": "एक छोटे से व्यवसाय की जरूरत",
"feat_sub": "किसी के लिए पर्याप्त आसान, एक वास्तविक व्यवसाय के लिए पर्याप्त शक्तिशाली।",
"feat1_t": "डेस्कटॉप + मोबाइल मिश्रण",
"feat1_d": "दो टेम्पलेट्स, एक साइट। प्रत्येक स्क्रीन का आकार इसके लिए डिज़ाइन किया गया एक लेआउट हो जाता है।",
"feat2_t": "34 एक-क्लिक प्लगइन",
"feat2_d": "दुकान, बुकिंग, मेनू, गैलरी, स्लाइड शो, समीक्षा, अक्सर पूछे जाने वाले प्रश्न, टीम, घटनाओं, नक्शे, न्यूजलेटर और अधिक।",
"feat3_t": "वैश्विक भाषा",
"feat3_d": "बिल्डर 14 भाषाओं को बोलता है और आपकी साइट गूगल के साथ 100+ भाषाओं में स्वतः अनुवाद कर सकती है।",
"feat4_t": "आपका डोमेन, आपका क्लाउड",
"feat4_d": "तुम सब कुछ मालिक हो। क्लाउडफ्लेयर पेज, नेटलीफाई, वर्सेल या किसी भी सर्वर पर होस्ट करें।",
"feat5_t": "एसईओ और विश्लेषण",
"feat5_d": "शीर्षक, विवरण, कीवर्ड, शेयर छवि, hreflang और अपने विश्लेषणात्मक कोड।",
"feat6_t": "सामाजिक",
"feat6_d": "यूट्यूब वीडियो, सोशल लिंक और व्हाट्सएप, टेलीग्राम, लाइन और वीचैट बटन।",
"faq_title": "अक्सर पूछे जाने वाले प्रश्न",
"faq1_q": "क्या मुझे कोडिंग जानने की आवश्यकता है?",
"faq1_a": "नहीं टेम्पलेट्स चुनें, अपनी सामग्री टाइप करें, प्लग ऑन करें और निर्यात करें। सब कुछ आपके ब्राउज़र में होता है।",
"faq2_q": "क्या आप मेरे लिए वेबसाइट डिजाइन करते हैं?",
"faq2_a": "नहीं। {brand} पूरी तरह सेल्फ-सर्विस है: आप हमारे टेम्पलेट और प्लगइन से अपनी साइट खुद डिज़ाइन करते हैं। हम डिज़ाइन सेवाएँ नहीं देते।",
"faq3_q": "क्या मैं ऑनलाइन उत्पाद बेच सकता हूँ?",
"faq3_a": "हाँ। ऑनलाइन शॉप प्लगइन में उत्पाद, आकार, स्टॉक, छूट कोड, एक गाड़ी और एक चेकआउट शामिल है जो आपके व्हाट्सएप या ईमेल को ऑर्डर भेजता है।",
"faq4_q": "क्या मुझे अपना डोमेन और होस्टिंग की आवश्यकता है?",
"faq4_a": "हाँ। आप अपना खुद का डोमेन खरीदते हैं और अपना खुद का क्लाउड होस्टिंग चुनते हैं। हमारे चरण-दर-चरण गाइड से पता चलता है कि उन्हें कैसे जोड़ा जाए।",
"faq5_q": "कौन से भाषाएँ समर्थित हैं?",
"faq5_a": "बिल्डर में 14 भाषाएं हैं। आपकी निर्यात की गई साइट उनके बीच स्विच कर सकती है, या Google के साथ 100+ भाषाओं में ऑटो-ट्रांसलेट कर सकती है।",
"faq6_q": "कितना खर्च होता है?",
"faq6_a": "दो मासिक योजना: प्रो HK$68 और बिजनेस HK$198. आपका पहला महीना एक ट्रायल महीने के रूप में भुगतान किया जाता है; कभी भी रद्द कर दिया।",
"cta_title": "वेबसाइट बनाने के लिए तैयार हैं?",
"cta_sub": "अब बिल्डर को आज़माएं। जब आप प्रकाशित करने के लिए तैयार हैं तो अपने ट्रायल महीने शुरू करें।",
"footer_tag": "स्वयं सेवा वेबसाइट और छोटे व्यवसायों के लिए ऑनलाइन दुकान बिल्डर।",
