"host_vc": "एक गिट रिपॉज़िटरी या वर्सेल CLI के साथ एक परियोजना बनाएं, तैनात करें, फिर प्रोजेक्ट सेटिंग → डोमेन के तहत अपना डोमेन जोड़ें।",
"host_vps": "अपने सर्वर पर, Nginx स्थापित करें, index.html को वेब रूट में अपलोड करें और Let's Encrypt के साथ HTTPS सक्षम करें।",
