"step3_t": "การรวม, ส่วนเสริมที่ปรับแต่งเอง",
"step3_d": "แก้ไขชื่อของคุณ, โลโก้, สี และข้อความ จากนั้นสลับปลั๊กอินต่าง ๆ: ร้านค้าออนไลน์, การจองโต๊ะ, เมนู, แกลเลอรี่, วิดีโอ และอื่นๆ",
"step4_t": "ดินแดนของคุณ + เมฆของคุณ ไปมีชีวิต",
"step4_d": "ส่งออกเป็นแฟ้มหนึ่ง แล้วทําการอัปโหลดมันมายังเครื่องของคุณ และชี้โดเมนของคุณเองไปยังมัน",
