"faq_title": "บ่อย ครั้ง มี การ ถาม คํา ถาม",
"faq1_q": "ฉันจําเป็นต้องรู้การเข้ารหัสเหรอ",
"faq1_a": "ไม่เลือกแม่แบบ, พิมพ์เนื้อหาของคุณ, เปลี่ยนส่วนเสริม และส่งออกทุกอย่างเกิดขึ้นในบราวเซอร์ของคุณ",
"faq2_q": "คุณออกแบบเว็บไซต์ให้ฉันไหม",
"faq2_a": "ไม่ {brand} เป็นบริการแบบทำเองทั้งหมด: คุณออกแบบเว็บไซต์เองด้วยเทมเพลตและปลั๊กอินของเรา เราไม่มีบริการรับออกแบบ",
"faq3_q": "ผมขายสินค้าออนไลน์ได้ไหม",
"faq3_a": "ใช่ส่วนเสริมร้านค้าออนไลน์เพิ่มผลิตภัณฑ์, ขนาด, หุ้น, รหัสส่วนลด, รถเข็น และเช็คเอาท์ที่ส่งคําสั่งไป ยังรายการของคุณ",
"faq4_q": "ฉันจําเป็นต้องมีโดเมนของตัวเอง และพิธีกร?",
"faq4_a": "ใช่คุณซื้อโดเมนของคุณเอง และเลือกพิธีกรเมฆของคุณเองไกด์ของเราทีละขั้น แสดงวิธีเชื่อมโยงพวกเขา",
"faq5_q": "มี การ สนับสนุน ภาษา ใด บ้าง?",
"faq5_a": "ผู้สร้างมี 14 ภาษาเว็บไซต์ส่งออกของคุณสามารถสลับระหว่างพวกเขา หรือ translate อัตโนมัติเป็น 100+ ภาษากับ Google",
"faq6_q": "มันราคาเท่าไหร่?",
"faq6_a": "2 แผนรายเดือน: Pro HK$68 และ Business HK198.เดือนแรกของคุณจ่ายล่วงหน้าเป็นเดือนทดลอง ยกเลิกได้ทุกเวลา",
